"""Rendering helpers for the Mantle prompt templates.

Templates are plain-text Jinja2 sources from
:mod:`rasa.mantle.prompts.templates`.  String templates render without
escaping — the output is prompt text, not HTML, and escaping would corrupt
quotes and ampersands in user-authored persona or rules text.
"""

from __future__ import annotations

import re
from functools import lru_cache
from typing import Any, List

from jinja2 import Environment, Template, select_autoescape

# Same autoescape policy as rasa.shared.utils.llm: no escaping for string
# templates, default escaping if a file-based template were ever added.
_TEMPLATE_ENV = Environment(
    autoescape=select_autoescape(default_for_string=False, default=True),
    trim_blocks=True,
    lstrip_blocks=True,
)

_HEADING_PREFIX = "## "
_LIST_ITEM_PREFIX = "- "


def render_template(template_source: str, **context: Any) -> str:
    """Render one prompt section and normalize its whitespace."""
    rendered = _compiled_template(template_source).render(**context).strip()
    return normalize_prompt_whitespace(rendered)


def join_sections(sections: List[str]) -> str:
    """Join non-empty prompt sections with one blank line between them."""
    visible_sections = [
        section.strip() for section in sections if section and section.strip()
    ]
    return "\n\n".join(visible_sections)


def normalize_prompt_whitespace(content: str) -> str:
    """Drop blank lines inside lists and after headings; collapse blank runs."""
    lines = [line.rstrip() for line in content.splitlines()]
    following_lines = _next_non_empty_lines(lines)

    kept_lines: List[str] = []
    previous = ""
    for line, following in zip(lines, following_lines):
        if line:
            kept_lines.append(line)
            previous = line
        elif _keep_blank_between(previous, following):
            kept_lines.append("")

    normalized = "\n".join(kept_lines).strip()
    return re.sub(r"\n{3,}", "\n\n", normalized)


@lru_cache(maxsize=64)
def _compiled_template(template_source: str) -> Template:
    """Compile a template source once; keyed on the interned constant."""
    return _TEMPLATE_ENV.from_string(template_source)


def _next_non_empty_lines(lines: List[str]) -> List[str]:
    """For each line, the next non-empty line after it (or "")."""
    following_lines = [""] * len(lines)
    upcoming = ""
    for index in range(len(lines) - 1, -1, -1):
        following_lines[index] = upcoming
        if lines[index]:
            upcoming = lines[index]
    return following_lines


def _keep_blank_between(previous: str, following: str) -> bool:
    """Whether a blank line belongs between two non-empty neighbours."""
    inside_list_block = previous.startswith(_LIST_ITEM_PREFIX) and following.startswith(
        _LIST_ITEM_PREFIX
    )
    after_heading_or_label = previous.startswith(_HEADING_PREFIX) or previous.endswith(
        ":"
    )
    return not inside_list_block and not after_heading_or_label
